import {AudioEngine} from './audio-engine.js';
import {zh,extraEn,glosses} from './i18n.js';
import {COLORS,renderHero,renderRecordPlot,renderArrangement} from './charts.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const en={...extraEn};$$('[data-i18n]').forEach(el=>{en[el.dataset.i18n]??=el.innerHTML});
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved=[];let language='en';try{language=localStorage.getItem('yi-language')||'en';saved=JSON.parse(localStorage.getItem('yi-notes')||'[]')}catch{}if(!Array.isArray(saved))saved=[];
const state={lang:language,pair:'pair-1',reference:false,time:'seconds',center:false,ending:false,revealed:false,region:null,melody:null,meaning:null,control:null,arrangeId:'ecura-0118',mode:'analysis',active:null,texture:'soft',activity:.4,presence:.35,accompaniment:true,positions:{}};
let data,recordMap,plots=[],arrPlot,toastTimer;const engine=new AudioEngine();const t=k=>(state.lang==='zh'?zh[k]:en[k])??en[k]??k;
const categoryMap={'梅葛本源':'Meige origin','相伙调':'Xianghu tune','喜庆调':'Celebration tune','喜庆梅葛':'Celebratory Meige','离别调':'Farewell tune'};
const short=id=>String(parseInt(id.split('-').at(-1),10));const fmt=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
const pair=()=>data.pairs.find(p=>p.id===state.pair);const records=()=>pair().recordIds.map(id=>recordMap.get(id)).concat(state.reference&&state.pair==='pair-1'?[recordMap.get('ecura-0116')]:[]);
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500)}
function setLanguage(lang){state.lang=lang;document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.title=lang==='zh'?'听见之间 · 彝族歌唱':'Between the Notes · Yi Singing';try{localStorage.setItem('yi-language',lang)}catch{}$$('[data-i18n]').forEach(el=>el.innerHTML=t(el.dataset.i18n));$('#language').textContent=lang==='zh'?'English':'中文';$('#language').ariaLabel=lang==='zh'?'Switch to English':'切换到中文';$('#interpretation').placeholder=t('interpretPlaceholder');if(data)renderAll()}
function renderAll(){renderSelectors();renderHero($('#hero-chart'),[recordMap.get('ecura-0118'),recordMap.get('ecura-0119')]);renderRecords();renderLyrics();renderResponses();renderArrange();renderMethods();updateTick()}
function renderSelectors(){
 $('#pair-count').textContent=data.corpus.matchedGroups;
 $('#pair-select').innerHTML=data.pairs.map((p,i)=>`<option value="${p.id}">${t('case')} ${i+1} · ${p.recordIds.map(short).join(' / ')}</option>`).join('');$('#pair-select').value=state.pair;
 $('#reference-toggle').hidden=state.pair!=='pair-1';$('#reference-toggle').textContent=t(state.reference?'removeReference':'addReference');$('#reference-toggle').setAttribute('aria-pressed',state.reference);
 $('#arrange-record').innerHTML=records().map(r=>`<option value="${r.id}">${short(r.id)} · ${escape(state.lang==='zh'?r.label:categoryMap[r.label]||r.label)}</option>`).join('');if(!records().some(r=>r.id===state.arrangeId))state.arrangeId=pair().recordIds[0];$('#arrange-record').value=state.arrangeId;
}
function renderRecords(){
 plots.forEach(p=>p.destroy());plots=[];const list=records();
 $('#recordings').innerHTML=list.map((r,i)=>`<article class="recording" data-id="${r.id}"><div class="recording-header"><button class="play-round" data-play="${r.id}" aria-label="${state.lang==='zh'?'播放':'Play'} ${short(r.id)}" style="color:${COLORS[i]}">▶</button><span class="record-id" style="color:${COLORS[i]}">${i<2?'AB'[i]:t('reference')} · ${short(r.id)} <span class="record-category">${escape(state.lang==='zh'?r.label:categoryMap[r.label]||r.label)}</span></span><span class="duration">${r.duration.toFixed(2)} s</span></div><div id="plot-${r.id}"></div><div class="seek-row"><label class="sr-only" for="seek-${r.id}">${state.lang==='zh'?'播放位置':'Playback position'} ${short(r.id)}</label><input id="seek-${r.id}" data-seek="${r.id}" type="range" min="0" max="${r.duration}" step=".01" value="${state.positions[r.id]||0}"><span class="mono" data-clock="${r.id}">${fmt(state.positions[r.id]||0)}</span></div></article>`).join('');
 list.forEach((r,i)=>plots.push(renderRecordPlot($(`#plot-${r.id}`),r,list,{index:i,relativeTime:state.time==='relative',relativePitch:state.center,ending:state.ending,region:state.region,t,onSeek:seekRecord,onRegion:(record,start,end)=>{engine.pause();state.region={id:record.id,start,end};state.positions[record.id]=start;renderRecords();renderRegion()}})));
 $$('[data-play]').forEach(el=>el.onclick=()=>playRecord(recordMap.get(el.dataset.play)));
 $$('[data-seek]').forEach(el=>el.oninput=()=>seekRecord(recordMap.get(el.dataset.seek),Number(el.value)));
 renderMetrics();renderRegion();updateTick();
}
function renderRegion(){const r=state.region;$('#clear-region').hidden=!r;$('#region-status').textContent=r?`${t('selected')}: ${short(r.id)} · ${r.start.toFixed(2)}–${r.end.toFixed(2)} s. ${t('selectionHint')}`:state.ending?t('earlyEnd'):state.reference?t('hasReference'):''}
function renderMetrics(){const list=records();const specs=[['duration',r=>r.duration,'s'],['pitchRange',r=>r.metrics.pitchRangeSemitones,t('semitones')],['lowEnergy',r=>100*r.metrics.lowEnergyRatio,'%']];$('#metric-chart').innerHTML='<div class="metric-grid">'+specs.map(([key,get,unit])=>{const max=Math.max(...list.map(get),.001);return `<div><h4>${t(key)}</h4>${list.map((r,i)=>`<div class="metric-line"><span>${short(r.id)}</span><div class="metric-track"><div class="metric-fill" style="width:${get(r)/max*100}%;background:${COLORS[i]}"></div></div><span class="metric-value">${get(r).toFixed(key==='duration'?2:1)} ${unit}</span></div>`).join('')}</div>`}).join('')+'</div><p>'+t('pitchCaution')+'</p>'}
async function playRecord(record){if(engine.playing&&state.active===record.id&&state.mode==='analysis'){engine.pause();updateTick();return}const reg=state.region?.id===record.id?state.region:null;let start=reg?.start??state.positions[record.id]??0;if(start>=record.duration-.1)start=0;state.mode='analysis';state.active=record.id;try{await engine.play(record,{start,end:reg?.end??record.duration,accompaniment:false});updateTick()}catch(e){console.error(e);toast(t('audioError'))}}
async function seekRecord(record,time){state.positions[record.id]=time;state.region=null;renderRegion();if(state.active===record.id&&state.mode==='analysis'){await engine.seek(time)}else{engine.pause();state.active=record.id;state.mode='analysis'}updateTick();if(!engine.playing)plots[records().findIndex(r=>r.id===record.id)]?.update(time,true)}
function renderResponses(){
 responseGroup('#melody-response',[['a',`A · ${short(pair().recordIds[0])}`],['b',`B · ${short(pair().recordIds[1])}`],['same',t('noDifference')],['unsure',t('notSure')]],'melody');
 responseGroup('#meaning-response',[['yes',t('yes')],['partly',t('partly')],['no',t('no')],['unsure',t('notSure')]],'meaning');
 if(!$('#control-feedback')){const div=document.createElement('div');div.id='control-feedback';div.className='control-feedback';$('.save-reflection').prepend(div)}
 $('#control-feedback').innerHTML=`<h3>${t('canControl')}</h3><div class="response-options" id="control-response"></div>`;
 responseGroup('#control-response',[['yes',t('helpYes')],['partly',t('helpPartly')],['no',t('helpNo')],['unsure',t('notSure')]],'control');
}
function responseGroup(selector,options,key){$(selector).innerHTML=options.map(([value,label])=>`<button data-value="${value}" class="${state[key]===value?'selected':''}" aria-pressed="${state[key]===value}">${escape(label)}</button>`).join('');$(selector).querySelectorAll('button').forEach(b=>b.onclick=()=>{state[key]=b.dataset.value;renderResponses()})}
function renderLyrics(){
 $('#reveal-lyrics').textContent=t(state.revealed?'hideLyrics':'reveal');$('#reveal-lyrics').setAttribute('aria-expanded',state.revealed);$('#meaning-reflection').hidden=!state.revealed;
 if(!state.revealed){$('#lyrics-panel').innerHTML=`<div class="hidden-lyrics"><span aria-hidden="true">“</span><p>${t('wordsHidden')}</p></div>`;return}
 $('#lyrics-panel').innerHTML=`<p class="lyric-original" lang="zh-CN">${escape(pair().text)}</p><p class="lyric-gloss" lang="en">${escape(glosses[state.pair]||'')}</p><p class="lyric-note">${t('glossNote')} ${t('sourceNote')}</p><details><summary>${t('ipaTitle')}</summary>${pair().recordIds.map(id=>`<p class="lyric-ipa"><strong>${short(id)}</strong> ${escape(recordMap.get(id).ipa)}</p>`).join('')}</details>`;
}
function plannedEvents(record){const planner=new AudioEngine();planner.record=record;planner.mix={texture:state.texture,activity:state.activity,presence:state.presence,accompaniment:state.accompaniment};return planner.getEvents()}
function renderArrange(){const record=recordMap.get(state.arrangeId);arrPlot=renderArrangement($('#arrange-chart'),record,plannedEvents(record),t);$$('[data-texture]').forEach(b=>{const selected=state.texture===b.dataset.texture;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected)});$('#activity').value=state.activity*100;$('#presence').value=state.presence*100;$('#original-mode').classList.toggle('selected',!state.accompaniment);$('#mix-mode').classList.toggle('selected',state.accompaniment);$('#original-mode').setAttribute('aria-pressed',!state.accompaniment);$('#mix-mode').setAttribute('aria-pressed',state.accompaniment);$('#arrange-status').textContent=t(state.accompaniment?'mixPlaying':'originalPlaying');updateTick()}
function mixOptions(){return {texture:state.texture,activity:state.activity,presence:state.presence,accompaniment:state.accompaniment}}
function setMix(options){Object.assign(state,options);if(state.mode==='arrange')engine.setMix(mixOptions());renderArrange()}
async function playArrangement(){if(engine.playing&&state.mode==='arrange'&&state.active===state.arrangeId){engine.pause();updateTick();return}const r=recordMap.get(state.arrangeId);let start=state.mode==='arrange'&&state.active===r.id?engine.currentTime:Number($('#arrange-seek').value)/1000*r.duration;if(start>=r.duration-.1)start=0;state.mode='arrange';state.active=r.id;try{await engine.play(r,{...mixOptions(),start});renderArrange();updateTick()}catch(e){console.error(e);toast(t('audioError'))}}
function updateTick(){if(!data)return;const time=engine.currentTime;const active=state.active;const currentList=records();currentList.forEach((r,i)=>{const same=state.mode==='analysis'&&r.id===active;const pos=same&&engine.record?.id===active?time:state.positions[r.id]||0;if(same)state.positions[r.id]=pos;plots[i]?.update(pos,same);const button=$(`[data-play="${r.id}"]`);if(button){button.textContent=same&&engine.playing?'Ⅱ':'▶';button.setAttribute('aria-label',`${same&&engine.playing?(state.lang==='zh'?'暂停':'Pause'):(state.lang==='zh'?'播放':'Play')} ${short(r.id)}`);button.closest('.recording').classList.toggle('active',same&&engine.playing)}const seek=$(`[data-seek="${r.id}"]`);if(seek&&document.activeElement!==seek)seek.value=pos;const clock=$(`[data-clock="${r.id}"]`);if(clock)clock.textContent=fmt(pos)});
 const r=recordMap.get(state.arrangeId);const same=state.mode==='arrange'&&active===r.id;const pos=same?time:Number($('#arrange-seek').value)/1000*r.duration;arrPlot?.update(pos,state.accompaniment);$('#arrange-clock').textContent=`${fmt(pos)} / ${fmt(r.duration)}`;$('#arrange-play').textContent=t(same&&engine.playing?'pause':'playMix');if(same&&document.activeElement!==$('#arrange-seek'))$('#arrange-seek').value=pos/r.duration*1000;
}
function renderMethods(){
 const cn=state.lang==='zh';
 $('#course-links').innerHTML=(cn?['<strong>L4，PDF 114–115 页：</strong>共享尺度的小多图，让眼睛直接比较。','<strong>L11，PDF 82–86 页：</strong>TimeSearcher 案例启发时间选择、局部查看与联动。','<strong>L12，PDF 39–41、65 页：</strong>逐步展开信息，并让选择联动多个视图。']:['<strong>L4, PDF pp. 114–115:</strong> Small multiples and shared scales reduce dependence on visual memory.','<strong>L11, PDF pp. 82–86:</strong> TimeSearcher examples inform time selection, local inspection and coordination.','<strong>L12, PDF pp. 39–41, 65:</strong> Reveal detail progressively and coordinate selections across views.']).map(s=>`<p>${s}</p>`).join('');
 $('#research-links').innerHTML=`<li><a href="https://vis.stanford.edu/files/2010-Narrative-InfoVis.pdf" target="_blank" rel="noopener">Segel & Heer (2010), Narrative Visualization</a> — ${cn?'引导式叙事与自由探索。':'guided stages with room for exploration.'}</li><li><a href="https://sonicvisualiser.org/sv2010.pdf" target="_blank" rel="noopener">Cannam, Landone & Sandler (2010), Sonic Visualiser</a> — ${cn?'音频特征与播放的共同时间轴。':'audio features aligned with playback.'}</li><li><a href="https://youralien.github.io/files/cococo_chi2020_copy.pdf" target="_blank" rel="noopener">Louie et al. (2020), Novice-AI Music Co-Creation</a> — ${cn?'少量高层控制与原版比较。此 demo 使用规则合成，没有使用论文中的 AI 模型；其研究也不证明本界面对所有新手有效。':'bounded controls and comparison with the original. This demo uses rule-based synthesis, not their AI model; usability here remains untested.'}</li>`;
 const m=data.method;
 $('#method-detail').innerHTML=escape(cn?`分析样本：17 条完整录音，包含 8 组同中文字段对照及 116 参考。\n算法：librosa ${m.librosaVersion}，pYIN；分析重采样至 ${m.sampleRate} Hz 单声道，播放保留原始 MP3。\n分析窗 ${m.frameLength}，步长 ${m.hopLength}；图表约每 ${Math.round(m.plotFrameSeconds*1000)} ms 一个样本。\n低能量：相对于每条录音的最大 RMS，低于 ${m.lowEnergyThresholdDb} dB 且至少 ${m.minLowEnergySeconds} 秒。\n音高：${m.fminHz.toFixed(1)}–${m.fmaxHz.toFixed(1)} Hz 搜索范围，发声概率阈值 ${m.voicedProbMin}，并非正确率阈值。\n所有指标尚待人工校正，未推断情绪或歌手意图。\n伴奏：规则调度的合成音色，以局部音高估计或中位音高为参考，不推断调式、和弦或文化真实性。\n全部 17 条样本均无字节或解码 PCM 完全重复；未排除近重复、重叠来源或其他混杂因素。`:`Analysis sample: 17 complete recordings: 8 exact Chinese-text pairs and reference 116.\nAlgorithm: librosa ${m.librosaVersion}, pYIN. Analysis audio is resampled to ${m.sampleRate} Hz mono; playback uses the original MP3s.\nFrame length ${m.frameLength}, hop ${m.hopLength}; plotted samples approximately every ${Math.round(m.plotFrameSeconds*1000)} ms.\nLow energy: below ${m.lowEnergyThresholdDb} dB relative to each recording's maximum RMS for at least ${m.minLowEnergySeconds}s.\nPitch search: ${m.fminHz.toFixed(1)}–${m.fmaxHz.toFixed(1)} Hz; voicing probability cutoff ${m.voicedProbMin}, not an accuracy threshold.\nEstimates await manual correction. No emotion or singer-intention inference.\nAccompaniment: rule-scheduled synthesis, using local or median pitch as a reference, with no key, chord or cultural-authenticity inference.\nNo byte-identical or decoded-PCM-identical duplicate among the 17 samples. Near duplicates, overlapping sources and confounds are not excluded.`)+`<p><a href="data/analysis-summary.json">${cn?'查看处理摘要':'View processing summary'}</a> · <a href="${m.references[0].url}" target="_blank" rel="noopener">pYIN documentation</a></p>`;
}
function saveNote(){const record={schemaVersion:1,createdAt:new Date().toISOString(),pairId:state.pair,recordIds:pair().recordIds,melody:state.melody,lyricsRevealed:state.revealed,meaning:state.meaning,arrangement:{recordId:state.arrangeId,...mixOptions(),engine:'energy-guided-synthesis-v1'},controlHelp:state.control,interpretation:$('#interpretation').value.trim(),language:state.lang};saved.push(record);try{localStorage.setItem('yi-notes',JSON.stringify(saved));$('#save-status').textContent=`${t('saved')} · ${saved.length} ${t('noteCount')}`}catch{$('#save-status').textContent=t('saveFailed')}}
function exportNotes(){if(!saved.length){toast(t('emptyExport'));return}const blob=new Blob([JSON.stringify({study:'Yi singing exploratory prototype',notControlledStudy:true,notes:saved},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='yi-listening-notes.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('downloaded'))}
$('#language').onclick=()=>setLanguage(state.lang==='en'?'zh':'en');
$('#pair-select').onchange=e=>{engine.stop();state.pair=e.target.value;state.reference=false;state.region=null;state.active=null;state.melody=null;state.meaning=null;state.control=null;state.revealed=false;state.arrangeId=pair().recordIds[0];$('#arrange-seek').value=0;$('#interpretation').value='';renderAll()};
$('#reference-toggle').onclick=()=>{if(state.reference&&state.active==='ecura-0116'){engine.stop();state.active=null;state.mode='analysis';$('#arrange-seek').value=0}state.reference=!state.reference;if(!state.reference&&state.region?.id==='ecura-0116')state.region=null;renderSelectors();renderRecords();renderArrange()};
$$('[data-time]').forEach(b=>b.onclick=()=>{state.time=b.dataset.time;$$('[data-time]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});renderRecords()});
$('#relative-pitch').onchange=e=>{state.center=e.target.checked;renderRecords()};$('#ending').onchange=e=>{state.ending=e.target.checked;renderRecords()};$('#clear-region').onclick=()=>{state.region=null;renderRecords()};
$('#reveal-lyrics').onclick=()=>{state.revealed=!state.revealed;renderLyrics()};
$('#arrange-record').onchange=e=>{engine.stop();state.arrangeId=e.target.value;state.mode='arrange';state.active=null;$('#arrange-seek').value=0;renderArrange()};
$$('[data-texture]').forEach(b=>b.onclick=()=>setMix({texture:b.dataset.texture}));$('#activity').oninput=e=>setMix({activity:Number(e.target.value)/100});$('#presence').oninput=e=>setMix({presence:Number(e.target.value)/100});$('#original-mode').onclick=()=>setMix({accompaniment:false});$('#mix-mode').onclick=()=>setMix({accompaniment:true});$('#arrange-play').onclick=playArrangement;
$('#arrange-seek').oninput=async e=>{const time=Number(e.target.value)/1000*recordMap.get(state.arrangeId).duration;if(state.mode==='arrange'&&state.active===state.arrangeId)await engine.seek(time);else arrPlot?.update(time,state.accompaniment);updateTick()};
$('#reset-arrange').onclick=()=>setMix({texture:'soft',activity:.4,presence:.35,accompaniment:true});$('#save-choice').onclick=saveNote;$('#export-notes').onclick=exportNotes;engine.onTick=updateTick;
setLanguage(state.lang);
try{const response=await fetch('data/demo.json');if(!response.ok)throw new Error(`HTTP ${response.status}`);data=await response.json();recordMap=new Map(data.records.map(r=>[r.id,r]));renderAll();window.__yiDemo={state,engine,data,version:'1.0.0',get savedNotes(){return [...saved]}}}catch(e){console.error(e);$('#recordings').innerHTML=`<p class="error">${t('loadFailed')}</p>`;toast(t('loadFailed'))}
